  for await (const chunk of req) { /* Original native SDK request body. */ }
  const result = req.url === '/supported' ? { kinds: [{ x402Version: 2, scheme: 'exact', network: 'stellar:testnet' }], extensions: ['bazaar'], signers: {} }
