    afterBoundary: { ...declaration.queries.events, parameters: { after: { type: 'string', maxLength: 41, enum: ['-'], default: '-' } } },
  };
  const connection = fixture ? fixture.connection : http ? { transport: 'upstash-rest', endpoint, token: password }
