  for (const certificate of REDIS_CERTIFICATE_FILES) {
    if (!source.connection[certificate.profile]) continue;
    certificates.set(certificate.file, await readLimited(resolve(dirname(original.path), source.connection[certificate.profile]), 1048576));
    source.connection[certificate.profile] = certificate.file;
