        await target.client.sendCommand(['CLUSTER', 'SETSLOT', String(slot), 'IMPORTING', from.id]);
        await from.client.sendCommand(['CLUSTER', 'SETSLOT', String(slot), 'MIGRATING', target.id]);
        let movedKeys = 0;
        for (;;) {
