      typeof meta.id !== 'string' || !/^redis-workspace-[a-f0-9-]{36}$/.test(meta.id) ||
      !plain(meta.profile) || meta.profile.schema !== 'stellar-forge.redis-source.v1' ||
      !plain(meta.profile.connection) ||
