    const scalarParameters = compiled[name].parameters;
    for (const spec of Object.values(scalarParameters)) {
      if (spec.type === 'string' && [spec.default, ...(spec.enum ?? [])].some(value =>
        typeof value === 'string' && value.includes('\0')))
