        payment:{network:'stellar:testnet', asset:'', payTo:'', maxTimeoutSeconds:60, paymentFlow:'authorization'},
        allowLoopbackUpstream:false, operations:opened.operations.map(row => ({...row, amountAtomic:''}))};
