            : original.name.endsWith('.tar') ? 'application/x-tar' : 'application/octet-stream'), bytes: size, sha256: sha } };
        this.#reads.set(read.id, read); handle = null; this.#touch(read); return read;
      } catch (error) {
        if (native && handle && !String(error.code ?? '').startsWith(this.#prefix + '_'))
          throw this.#fail('SNAPSHOT_UNAVAILABLE', 'The original native descriptor could not be verified. Reopen its original artifact.');
        throw error;
      } finally {
        await handle?.close().catch(() => {});
      }
    });
    let opening = this.#opening.get(scope);
    if (!opening) { opening = new Set(); this.#opening.set(scope, opening); }
    opening.add(pending);
    const remove = () => { opening.delete(pending); if (!opening.size) this.#opening.delete(scope); };
    this.#readTail = pending.then(remove, remove);
    return pending;
  }
  async read(options) {
    const { scope, key, readId, expectedSha256, offset = 0, limit = 65536 } = options;
    this.#assertOpening(scope);
    if (!Number.isSafeInteger(offset) || offset < 0 || !Number.isSafeInteger(limit) || limit < 1 || limit > MAX_RETAINED_CHUNK_BYTES ||
        expectedSha256 !== undefined && !SHA256.test(expectedSha256))
      throw this.#fail('INVALID_CHUNK', 'Use a nonnegative byte offset, a bounded chunk and an exact SHA256.');
    if ((offset > 0 || readId) && !expectedSha256)
      throw this.#fail('INVALID_CHUNK', 'Repeat expectedSha256 when continuing a read or resuming at a later offset.');
    const read = readId ? this.#reads.get(readId) : await this.#open(options);
    if (!read || read.closed || read.releasing)
      throw this.#fail('READ_NOT_FOUND', 'This file read completed, expired or was released. Open a new original read using the same expectedSha256 to resume.');
    if (read.scope !== scope || read.key !== key) throw this.#fail('READ_CONFLICT', 'Use this readId only for its original scope and file selection.');
    if (expectedSha256 && expectedSha256 !== read.metadata.sha256) throw this.#fail('FILE_CHANGED', 'The read snapshot differs from the requested SHA256.');
    if (offset > read.size) { if (!readId) await this.release(scope, read.id); throw this.#fail('INVALID_CHUNK', 'Use an offset within the verified original file.'); }
    const pending = read.tail.then(async () => {
      if (read.closed) throw this.#fail('READ_NOT_FOUND', 'This original file read has completed or been released.');
      this.#touch(read);
      try {
        const identity = read.native ? await this.#beforeNativeChunk(read) : null;
        const length = Math.min(limit, read.size - offset), chunk = read.memory ? read.memory.subarray(offset, offset + length) : Buffer.alloc(length);
        if (read.handle) {
          let position = 0;
          while (position < length) {
            const result = await read.handle.read(chunk, position, length - position, offset + position);
            if (!result.bytesRead) throw this.#fail('SNAPSHOT_UNAVAILABLE', 'The private verified read snapshot is unavailable.');
            position += result.bytesRead;
          }
        }
        if (read.native && !sameIdentity(identity, await this.#nativeIdentity(read.handle)))
          throw this.#fail('FILE_CHANGED', 'The native file changed while this chunk was read. No bytes from that chunk were accepted.');
        const next = offset + length, result = { readId: read.id, file: read.metadata, offset, bytesRead: length,
          nextOffset: next < read.size ? next : null, encoding: 'base64', data: chunk.toString('base64') };
        if (next === read.size) await this.#dispose(read);
        return result;
      } catch (error) {
        if (read.native) {
          await this.#dispose(read).catch(() => {});
          if (!String(error.code ?? '').startsWith(this.#prefix + '_'))
            throw this.#fail('SNAPSHOT_UNAVAILABLE', 'The original native descriptor is unavailable. Reopen its original artifact.');
        }
        throw error;
      }
    });
    read.tail = pending.then(() => {}, () => {});
    return pending;
  }
  close() {
    if (!this.#close) {
      this.#closing = true;
      this.#close = (async () => {
        await this.#readTail;
        await Promise.all([...this.#reads.values()].map(read => this.release(read.scope, read.id)));
      })();
    }
    return this.#close;
  }
}

#!/usr/bin/env node
// MIT. Private merchant receiving review over original source and public reads.
import { readFile, open, mkdir, rm, stat } from 'node:fs/promises';
import { resolve, join, isAbsolute } from 'node:path';
import { pathToFileURL } from 'node:url';
import { merchantReadinessHtml, merchantReadinessCsv } from './merchant.mjs';
import { inspectMerchantReceiving, compareMerchantReadiness } from './receiving-session.mjs';
import { sha256 } from './readiness.mjs';

const HELP = `Usage: node merchant-cli.mjs --config SELLER_JSON --out NEW_PRIVATE_DIRECTORY
  [--asset-map ASSET_MAP_JSON] [--origin ACTUAL_SELLER_ORIGIN] [--rpc-map RPC_MAP_JSON]
  [--https-proxy-env ENV_NAME] [--timeout-ms 12000] [--fee-operations 0]
  [--previous PREVIOUS_REVIEW_DIRECTORY] [--from-capture RETAINED_REVIEW_DIRECTORY]

Saved operator desk: merchant-readiness workspace --directory /absolute/private/desk
  [--port 8408] [--base-path /merchant/receiving]

Reviews every original SF30 option using native token reads and the original SAC
receiving evaluator. Existing exact asset maps are accepted; other SAC identities
are resolved from their deployed metadata and verified with the native SDK.
Writes private review.json, review.html, options.csv, plan.json, asset-map.json,
capture.json and manifest.json. Replay makes the same captured requests offline.
Exit 0: all recipients ready. Exit 2: merchant action/configuration/source review.
Exit 1: provider read failed. Exit 3: invalid input or output failure.
Guide: MERCHANT_READINESS.md`;

async function jsonInput(path) {
  const absolute = resolve(path), info = await stat(absolute);
  if (!info.isFile() || info.size > 1024*1024) throw new Error('INPUT_MUST_BE_JSON_FILE_UNDER_1_MIB');
  const bytes = await readFile(absolute);
  if (bytes.length > 1024*1024) throw new Error('INPUT_TOO_LARGE');
  return {json:JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes)),
    source:{path:absolute,bytes:bytes.length,sha256:sha256(bytes)}};
}

/** Reuse the original explicit CONNECT/TLS transport only when requested. */
export async function createReadinessFetch(proxyEnv, {environment = process.env, timeoutMs = 12000} = {}) {
  if (proxyEnv === undefined) return globalThis.fetch;
  if (!/^[A-Za-z_][A-Za-z0-9_]{0,127}$/.test(proxyEnv) || typeof environment[proxyEnv] !== 'string')
    throw new Error('EXPLICIT_PROXY_ENVIRONMENT_REQUIRED');
  const {createPublicHttpsFetch,normalizeBuyerTransport,resolveBuyerProxy} = await import('../sf31-buyer-client/public-transport.mjs');
  // Resolve this caller's environment now; the original transport receives the
  // same verified proxy URL and retains the exact target origin/TLS identity.
  const transports = new Map();
  return (url, init) => {
    const origin = new URL(url).origin;
    if (!transports.has(origin)) {
      const profile = normalizeBuyerTransport({mode:'explicit-connect',origin,proxyEnv});
      resolveBuyerProxy(profile,environment);
      transports.set(origin,createPublicHttpsFetch({timeoutMs,
        trustedProxy:{mode:'explicit-connect',origin,proxyUrl:environment[proxyEnv]}}));
    }
    return transports.get(origin)(url,init);
  };
}

export async function writeMerchantReview(directory, report, sources, bundle) {
  if (!isAbsolute(directory) || resolve(directory) !== directory) throw new Error('ABSOLUTE_NORMALIZED_OUTPUT_REQUIRED');
  // Own the directory only after this exclusive creation succeeds.
  await mkdir(directory,{mode:0o700});
  try {
    const files = {'review.json':JSON.stringify(report,null,2)+'\n','review.html':merchantReadinessHtml(report),
      'options.csv':merchantReadinessCsv(report),...(bundle ? {
        'plan.json':JSON.stringify(bundle.plan,null,2)+'\n',
        'asset-map.json':JSON.stringify(bundle.resolvedAssetMap,null,2)+'\n',
        'capture.json':JSON.stringify(bundle.capture,null,2)+'\n'} : {})};
    const manifest = {schema:'stellar-forge.merchant-readiness-manifest.v1',createdAt:new Date().toISOString(),
      sources,planDigest:report.planDigest,files:Object.entries(files).map(([name,text])=>
        ({name,bytes:Buffer.byteLength(text),sha256:sha256(text)}))};
    files['manifest.json'] = JSON.stringify(manifest,null,2)+'\n';
    for (const [name,text] of Object.entries(files)) {
      const handle = await open(join(directory,name),'wx',0o600);
      try { await handle.writeFile(text); await handle.sync(); } finally { await handle.close(); }
    }
    return manifest;
  } catch (error) {
    await rm(directory,{recursive:true,force:true});
    throw error;
  }
}

/** Resolve only named files whose exact bytes are committed by the private manifest. */
export async function readMerchantBundle(directory, name) {
  if (!['review.json','capture.json'].includes(name)) throw new Error('INVALID_BUNDLE_MEMBER');
  const root = resolve(directory), manifest = await jsonInput(join(root,'manifest.json'));
  if (manifest.json.schema !== 'stellar-forge.merchant-readiness-manifest.v1' || !Array.isArray(manifest.json.files))
    throw new Error('INVALID_MERCHANT_MANIFEST');
  const matches = manifest.json.files.filter(file=>file.name === name);
  if (matches.length !== 1) throw new Error('MANIFEST_MEMBER_MISSING');
  const expected = matches[0], path = join(root,name), info = await stat(path), max = name === 'capture.json' ? 80*1024*1024 : 8*1024*1024;
  if (!info.isFile() || !Number.isSafeInteger(expected.bytes) || expected.bytes < 0 || expected.bytes > max || info.size !== expected.bytes)
    throw new Error('MANIFEST_SIZE_MISMATCH');
  const bytes = await readFile(path);
  if (bytes.length !== expected.bytes || sha256(bytes) !== expected.sha256) throw new Error('MANIFEST_DIGEST_MISMATCH');
  return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));
}

export async function run(argv = process.argv.slice(2)) {
  if (argv[0] === 'workspace') {
    const {main} = await import('./workspace/server.mjs');
    await main(argv.slice(1)); return 0;
  }
  if (argv.length === 0 || argv.includes('--help')) { console.log(HELP); return 0; }
  const values = new Map(), allowed = new Set(['--config','--asset-map','--out','--rpc-map',
    '--https-proxy-env','--timeout-ms','--fee-operations','--origin','--previous','--from-capture']);
  for (let index = 0; index < argv.length; index += 2) {
    if (!allowed.has(argv[index]) || values.has(argv[index]) || !argv[index+1] || argv[index+1].startsWith('--'))
      throw new Error('INVALID_COMMAND_ARGUMENT');
    values.set(argv[index],argv[index+1]);
  }
  for (const key of ['--config','--out']) if (!values.has(key)) throw new Error('MISSING_REQUIRED_ARGUMENT');
  const number = (key,fallback) => {
    if (!values.has(key)) return fallback;
    if (!/^(0|[1-9]\d{0,8})$/.test(values.get(key))) throw new Error('INVALID_NUMERIC_ARGUMENT');
    return Number(values.get(key));
  };
  const [assets,rpc,capture,previous] = await Promise.all([
    values.has('--asset-map') ? jsonInput(values.get('--asset-map')) : null,
    values.has('--rpc-map') ? jsonInput(values.get('--rpc-map')) : null,
    values.has('--from-capture') ? readMerchantBundle(values.get('--from-capture'),'capture.json') : null,
    values.has('--previous') ? readMerchantBundle(values.get('--previous'),'review.json') : null,
  ]);
  const timeoutMs = number('--timeout-ms',12000), feeOperations = number('--fee-operations',capture?.feeOperations ?? 0);
  const fetchImpl = capture ? undefined : await createReadinessFetch(values.get('--https-proxy-env'),{timeoutMs});
  const bundle = await inspectMerchantReceiving({configPath:values.get('--config'),origin:values.get('--origin'),
    assetMap:assets?.json,rpcEndpoints:rpc?.json,timeoutMs,feeOperations,fetchImpl,capture:capture ?? undefined,liveTransport:!capture});
  const report = bundle.report;
  if (previous) report.comparison = compareMerchantReadiness(previous,report);
  const output = values.get('--out');
  await writeMerchantReview(output,report,{seller:report.configuration,
    ...(assets ? {assetMap:assets.source} : {}),...(rpc ? {rpcMap:rpc.source} : {})},bundle);

  console.log(JSON.stringify({status:report.status,...report.summary,output}));
  return report.summary.readFailed ? 1 : report.summary.ready === report.summary.options ? 0 : 2;
}

if (process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url) {
  // Finish this module before the workspace imports its original bundle helpers.
  // Awaiting the dynamic workspace import here would form a top-level-await cycle.
  run().then(code => { process.exitCode = code; }, error => {
    // Provider URLs and bodies may contain credentials. Emit stable codes only.
    const code = error.code ?? error.message;
    console.error(JSON.stringify({error:typeof code === 'string' && /^[A-Z0-9_]{1,100}$/.test(code) ? code : 'MERCHANT_READINESS_FAILED'}));
    process.exitCode = 3;
  });
}

// MIT. Linux flock retained by the gateway's own open file description.
import { spawnSync } from 'node:child_process';
import { constants, openSync, fstatSync, lstatSync, closeSync } from 'node:fs';
import { join } from 'node:path';

export async function acquireStateLease(directory) {
  const path = join(directory, 'lease.lock');
  const fd = openSync(path, constants.O_CREAT | constants.O_RDWR | constants.O_NOFOLLOW, 0o600);
  let closed = false;
  const assertHeld = () => {
    if (closed) throw new Error('FLEET_STATE_LEASE_LOST');
    const stat = fstatSync(fd);
    const named = lstatSync(path);
    if (!stat.isFile() || !named.isFile() || named.isSymbolicLink() ||
        (stat.mode & 0o077) || stat.dev !== named.dev || stat.ino !== named.ino)
      throw new Error('FLEET_PRIVATE_LEASE_REQUIRED');
  };
  try {
    assertHeld();
    // fd3 is a duplicate of OUR open file description, not a second open.
    // Successful helper exit leaves its flock held by the retained parent fd.
    // Parent close/crash releases it; no surviving helper or stale-PID recovery.
    const result = spawnSync('flock', ['--exclusive', '--nonblock', '--conflict-exit-code', '73', '3'],
      { stdio: ['ignore', 'pipe', 'pipe', fd], timeout: 10000 });
    if (result.error) throw Object.assign(new Error(result.error.code === 'ENOENT' ?
      'FLEET_LINUX_FLOCK_REQUIRED' : 'FLEET_STATE_LEASE_FAILED'), { cause: result.error });
    if (result.status !== 0) throw new Error(result.status === 73 ?
      'FLEET_STATE_ALREADY_OWNED' : 'FLEET_STATE_LEASE_FAILED');
    assertHeld();
    return {
      pid: process.pid, assertHeld,
      async close() { if (!closed) { closed = true; closeSync(fd); } },
    };
  } catch (error) { closed = true; closeSync(fd); throw error; }
}

// MIT. Native discovery and retained reads composed with the original SAC reviewer.
import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { readSellerConfig } from '../sf30-seller-sdk/serve.mjs';
import { formatAtomic } from '../sf16-asset-engine/assets.mjs';
import { amountText, sha256 } from './readiness.mjs';
import { createSacAssetMap, createSacRecipientReviewer, resolveSacRpcEndpoint } from './sac.mjs';
import { compileSellerReadinessPlan, reviewSellerSacReadiness, summarizeMerchantReadiness } from './merchant.mjs';
import { createNativeReader, createReadTransport, loadStellarSdk, fault } from './native-reader.mjs';

const serial = value => JSON.stringify(value);
const key = terms => serial([terms.network,terms.asset]);
const codeOf = error => typeof error?.code === 'string' && /^[A-Z0-9_]{1,100}$/.test(error.code)
  ? error.code : 'NATIVE_READ_FAILED';
const captureRead = async task => { try { return {value:await task()}; } catch (error) { return {error:codeOf(error)}; } };

export async function readMerchantReceivingPlan(configPath, {origin} = {}) {
  const path = resolve(configPath), before = await readFile(path);
  if (before.length > 1024*1024) throw fault('SELLER_CONFIG_TOO_LARGE');
  const config = await readSellerConfig(path), after = await readFile(path);
  if (!before.equals(after)) throw fault('SELLER_CONFIG_CHANGED_DURING_READ');
  if (!config.publicOrigin && !origin) throw fault('SELLER_ORIGIN_REQUIRED');
  const plan = compileSellerReadinessPlan(config,{origin});
  const configuration = {path,bytes:before.length,sha256:sha256(before),publicOrigin:plan.publicOrigin};
  return {config,plan,configuration,planDigest:sha256(serial(plan))};
}

/** The original SAC G-account evaluator remains the only classic receiving engine. */
export async function inspectMerchantReceiving({configPath,origin,assetMap,rpcEndpoints,environment = process.env,
  timeoutMs = 12000,feeOperations = 0,capture,sdk,fetchImpl,liveTransport = false} = {}) {
  origin ??= capture?.publicOrigin;
  const source = await readMerchantReceivingPlan(configPath,{origin});
  if (capture && (capture.planDigest !== source.planDigest || capture.configurationSha256 !== source.configuration.sha256))
    throw fault('CAPTURE_SELLER_PLAN_MISMATCH');
  if (capture && assetMap !== undefined && serial(assetMap) !== serial(capture.inputAssetMap)) throw fault('CAPTURE_ASSET_MAP_MISMATCH');
  if (capture && feeOperations !== capture.feeOperations) throw fault('CAPTURE_FEE_OPERATIONS_MISMATCH');
  assetMap ??= capture?.inputAssetMap ?? undefined;
  sdk ??= await loadStellarSdk();
  const supplied = assetMap ? await createSacAssetMap(assetMap,{sdk}) : null;
  const terms = source.plan.routes.flatMap(route=>route.accepts);
  const selected = rpcEndpoints ?? capture?.endpoints ?? {}, endpoints = {};
  for (const network of new Set(terms.map(term=>term.network))) {
    try { endpoints[network] = {url:resolveSacRpcEndpoint(network,selected,environment)}; }
    catch { if (selected[network] !== undefined) endpoints[network] = selected[network]; }
  }
  if (capture && serial(endpoints) !== serial(capture.endpoints)) throw fault('CAPTURE_ENDPOINTS_MISMATCH');
  const transport = createReadTransport({capture,fetchImpl,liveTransport});
  const native = createNativeReader({sdk,transport,endpoints,environment,timeoutMs});
  const tokens = new Map(), mappings = new Map((supplied?.entries() ?? []).map(row=>[key(row),row]));
  for (const term of terms) if (!tokens.has(key(term))) {
    const result = await captureRead(()=>native.token(term.network,term.asset));
    tokens.set(key(term),result);
    if (result.value?.kind === 'STELLAR_ASSET_CONTRACT' && !mappings.has(key(term))) {
      const token = result.value;
      mappings.set(key(term),{network:term.network,asset:term.asset,classicAsset:token.classic,
        source:`Native SDK verified RPC metadata at ${token.rpcOrigin}; ledger ${token.instanceLedger}; endpoint ${token.endpointDigest}`});
    }
  }
  const resolvedAssetMap = {schema:'stellar-forge.sac-asset-map.v1',assets:[...mappings.values()]};
  const sac = mappings.size ? await createSacRecipientReviewer({assetMap:resolvedAssetMap,rpcEndpoints:endpoints,
    environment,timeoutMs,feeOperations,fetchImpl:transport.fetch,sdk}) : null;
  const reviewer = {review:async payment => {
    const found = tokens.get(key(payment));
    if (!found?.value) throw fault(found?.error ?? 'NATIVE_TOKEN_READ_MISSING');
    const token = found.value, isAccount = sdk.StrKey.isValidEd25519PublicKey(payment.payTo);
    if (!isAccount && !sdk.StrKey.isValidContract(payment.payTo)) throw fault('INVALID_G_ADDRESS');
    const read = await captureRead(()=>native.recipient(payment.network,payment.asset,payment.payTo));
    const nativeResult = {token,amountDecimal:formatAtomic(payment.amount,token.decimals),
      recipient:read.value ?? null,errors:read.error ? [read.error] : []};
    let result;
    if (token.kind === 'STELLAR_ASSET_CONTRACT' && isAccount) {
      result = structuredClone(await sac.review(payment));
    } else {
      result = {schema:'stellar-forge.sac-recipient-readiness.v1',terms:structuredClone(payment),
        mapping:mappings.get(key(payment)) ?? null,classic:null,contract:token.instance,
        observedAtMs:Date.now(),completedAt:new Date().toISOString(),reasons:[],accountAdvisories:[],
        status:token.kind === 'STELLAR_ASSET_CONTRACT' ? 'SAC_RECIPIENT_READY' : 'REVIEW_REQUIRED',
        ready:token.kind === 'STELLAR_ASSET_CONTRACT'};
      if (token.kind === 'CUSTOM_CONTRACT') result.reasons.push('CUSTOM_CONTRACT_RECEIVING_POLICY');
    }
    result.native = nativeResult;
    const add = (code,status='ACTION_REQUIRED') => {
      if (!result.reasons.includes(code)) result.reasons.push(code);
      result.ready = false;
      if (result.status !== 'ACTION_REQUIRED') result.status = status;
    };
    if (read.error) add(read.error,'READ_FAILED');
    else {
      const recipient = read.value;
      if (recipient.authorized === false) add('NATIVE_RECIPIENT_NOT_AUTHORIZED');
      const max = (1n << (isAccount && token.kind === 'STELLAR_ASSET_CONTRACT' ? 63n : 127n)) - 1n;
      if (BigInt(recipient.balanceAtomic) + BigInt(payment.amount) > max) add('TOKEN_BALANCE_LIMIT_EXCEEDED');
      if (result.classic?.recipient.existingBalance !== null && result.classic?.recipient.existingBalance !== undefined &&
        amountText(recipient.balanceAtomic) !== result.classic.recipient.existingBalance)
        add('NATIVE_CLASSIC_BALANCE_CHANGED','REVIEW_REQUIRED');
      if (result.classic && token.classic !== 'native' && recipient.authorized !== null &&
        (result.classic.recipient.authorization === 'AUTHORIZED') !== recipient.authorized)
        add('NATIVE_CLASSIC_AUTHORIZATION_CHANGED','REVIEW_REQUIRED');
      const ledgers = [token.instanceLedger,...token.metadataLedgers,recipient.balanceLedger,
        ...(recipient.authorizationLedger ? [recipient.authorizationLedger] : [])];
      if (Math.max(...ledgers)-Math.min(...ledgers) > 12) add('NATIVE_LEDGER_SKEW','REVIEW_REQUIRED');
    }
    return result;
  }};
  let report = await reviewSellerSacReadiness(source.config,{reviewer,origin});
  const reads = transport.reads(), now = Date.now();
  const oldest = reads.length ? Math.min(...reads.map(read=>Date.parse(read.observedAt))) : now;
  const changed = await captureRead(()=>readFile(source.configuration.path));
  const configurationUnchanged = changed.value !== undefined && sha256(changed.value) === source.configuration.sha256;
  const sourceReasons = [
    ...(transport.mode !== 'LIVE_NETWORK_READS' ? ['RETAINED_SOURCE_REVIEW'] : []),
    ...(now-oldest > 60000 || now < oldest ? ['OBSERVATION_STALE'] : []),
    ...(!configurationUnchanged ? ['SELLER_CONFIG_CHANGED_DURING_CHECK'] : []),
  ];
  if (sourceReasons.length) report.options = report.options.map(row=> {
    if (!row.readiness) return row;
    const readiness = {...row.readiness,reasons:[...new Set([...row.readiness.reasons,...sourceReasons])],ready:false};
    if (readiness.status === 'SAC_RECIPIENT_READY') readiness.status = 'REVIEW_REQUIRED';
    return {...row,status:readiness.status,readiness};
  });
  report = summarizeMerchantReadiness({...report,mode:transport.mode,configuration:{...source.configuration,
    unchangedAtCompletion:configurationUnchanged},sourceReasons,readCount:reads.length});
  return {plan:source.plan,report,resolvedAssetMap,capture:{schema:'stellar-forge.sf101.merchant-capture.v1',
    planDigest:source.planDigest,configurationSha256:source.configuration.sha256,publicOrigin:source.plan.publicOrigin,
    inputAssetMap:assetMap ?? null,
    endpoints,feeOperations,mode:transport.mode,reads}};
}

export function compareMerchantReadiness(previous,current) {
  if (previous?.schema !== 'stellar-forge.seller-sac-readiness.v1' || !Array.isArray(previous.options)) throw fault('PREVIOUS_REPORT_INVALID');
  // Option position can change; payment identity includes the complete original terms and resource.
  const identity = row => serial([row.routeId,row.method,row.url,row.terms]);
  const reasons = row => row?.readiness?.reasons ?? (row?.errorCode ? [row.errorCode] : []);
  const before = new Map(previous.options.map(row=>[identity(row),row])), seen = new Set(), options = [];
  for (const row of current.options) {
    const id = identity(row), prior = before.get(id); seen.add(id);
    options.push({routeId:row.routeId,optionIndex:row.optionIndex,optionId:row.optionId,
      change:!prior?'ADDED':serial([prior.status,reasons(prior)])===serial([row.status,reasons(row)])?'UNCHANGED':'CHANGED',
      before:prior?.status ?? null,after:row.status,resolved:reasons(prior).filter(code=>!reasons(row).includes(code)),
      introduced:reasons(row).filter(code=>!reasons(prior).includes(code))});
  }
  for (const row of previous.options) if (!seen.has(identity(row))) options.push({routeId:row.routeId,optionIndex:row.optionIndex,
    optionId:row.optionId,change:'REMOVED',before:row.status,after:null,resolved:[],introduced:[]});
  return {previousCompletedAt:previous.completedAt,previousPlanDigest:previous.planDigest,currentPlanDigest:current.planDigest,options};
}

// MIT. Native SDK serialization and read-only Stellar RPC observations for SF101.
import { createHash } from 'node:crypto';
import { SAC_NETWORKS as NETWORKS, resolveSacRpcEndpoint, decodeSacInstance } from './sac.mjs';
export { NETWORKS };
const READ_METHODS = new Set(['getNetwork', 'getLedgerEntries', 'simulateTransaction']);
const MAX_BODY = 2 * 1024 * 1024;
const MAX_CAPTURE = 64 * 1024 * 1024;
const hash = bytes => createHash('sha256').update(bytes).digest('hex');
export function fault(code, message = code) { return Object.assign(new Error(message), {code}); }
const requireThat = (ok, code) => { if (!ok) throw fault(code); };
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);

export async function loadStellarSdk() {
  try { return await import('@stellar/stellar-sdk'); }
  catch (error) { throw fault('STELLAR_SDK_REQUIRED', 'Install the original optional @stellar/stellar-sdk dependency in this application: ' + error.code); }
}

/** Retain original HTTP bytes; replay addresses the same exact serialized request. */
export function createReadTransport({capture, fetchImpl = fetch, liveTransport = false} = {}) {
  if (capture !== undefined) requireThat(object(capture) && capture.schema === 'stellar-forge.sf101.merchant-capture.v1' &&
    Array.isArray(capture.reads) && capture.reads.length <= 10000, 'INVALID_CAPTURE');
  const recorded = new Map();
  let size = 0;
  for (const item of capture?.reads ?? []) {
    requireThat(object(item) && object(item.request) && (typeof item.raw === 'string' || object(item.failure)) &&
      (item.failure || item.sha256 === hash(item.raw) && item.bytes === Buffer.byteLength(item.raw)) &&
      (item.failure || Number.isInteger(item.status) && item.status >= 100 && item.status <= 599) &&
      Number.isFinite(Date.parse(item.observedAt)) && !recorded.has(item.key), 'INVALID_CAPTURE_ENTRY');
    requireThat(item.key === hash(JSON.stringify(item.request)), 'CAPTURE_REQUEST_DIGEST_MISMATCH');
    size += Buffer.byteLength(item.raw ?? '');
    requireThat(Buffer.byteLength(item.raw ?? '') <= MAX_BODY && size <= MAX_CAPTURE, 'CAPTURE_TOO_LARGE');
    recorded.set(item.key, structuredClone(item));
  }
  const used = new Map();
  async function recordedFetch(url, init = {}) {
    const request = {url:String(url), method:init.method ?? 'GET', body:init.body ?? null};
    requireThat(request.method === 'GET' || request.method === 'POST', 'READ_METHOD_REQUIRED');
    if (request.method === 'POST') {
      let body;
      try { body = JSON.parse(request.body); } catch { throw fault('RPC_BODY_INVALID'); }
      requireThat(READ_METHODS.has(body.method), 'RPC_READ_METHOD_REQUIRED');
    }
    const key = hash(JSON.stringify(request));
    let item = recorded.get(key);
    if (capture !== undefined) requireThat(item, 'CAPTURE_REQUEST_MISSING');
    if (!item) {
      let response;
      try { response = await fetchImpl(url, {...init, redirect:'manual'}); }
      catch (error) {
        item = {key,request,observedAt:new Date().toISOString(),failure:{
          code:String(error.code ?? error.cause?.code ?? 'READ_TRANSPORT_FAILED').slice(0,80),
          message:String(error.message ?? 'Read transport failed').slice(0,300)}};
        recorded.set(key,item); used.set(key,item);
        throw fault(item.failure.code,item.failure.message);
      }
      const chunks = []; let bytes = 0;
      if (response.body) for await (const chunk of response.body) {
        bytes += chunk.length;
        requireThat(bytes <= MAX_BODY && size + bytes <= MAX_CAPTURE, 'READ_RESPONSE_TOO_LARGE');
        chunks.push(chunk);
      }
      const raw = new TextDecoder('utf-8', {fatal:true}).decode(Buffer.concat(chunks));
      item = {key,request,status:response.status,raw,sha256:hash(raw),bytes,
        observedAt:new Date().toISOString()};
      size += bytes;
      recorded.set(key,item);
    }
    used.set(key,item);
    if (item.failure) throw fault(item.failure.code,item.failure.message);
    return new Response([204,205,304].includes(item.status) ? null : item.raw,
      {status:item.status,headers:{'content-type':'application/json'}});
  }
  return {fetch:recordedFetch, mode:capture !== undefined ? 'RETAINED_NETWORK_READS' :
    fetchImpl === fetch || liveTransport ? 'LIVE_NETWORK_READS' : 'CALLER_TRANSPORT_READS',
    reads:() => [...used.values()].map(value => structuredClone(value))};
}

export function createNativeReader({sdk, transport, endpoints = {}, environment = process.env, timeoutMs = 12000}) {
  requireThat(Number.isInteger(timeoutMs) && timeoutMs >= 1000 && timeoutMs <= 30000, 'INVALID_TIMEOUT');
  const networks = new Map(), tokens = new Map(), balances = new Map();
  const memo = (map, key, task) => {
    if (!map.has(key)) map.set(key, Promise.resolve().then(task));
    return map.get(key);
  };
  async function rpc(endpoint, method, params = {}) {
    requireThat(READ_METHODS.has(method), 'RPC_READ_METHOD_REQUIRED');
    const id = 'sf101-' + method;
    const response = await transport.fetch(endpoint, {method:'POST',headers:{'content-type':'application/json'},
      body:JSON.stringify({jsonrpc:'2.0',id,method,params}),signal:AbortSignal.timeout(timeoutMs)});
    requireThat(response.ok, 'RPC_HTTP_' + response.status);
    const message = await response.json();
    requireThat(object(message) && message.jsonrpc === '2.0' && message.id === id, 'RPC_ENVELOPE_MISMATCH');
    if (message.error) throw fault('RPC_PROVIDER_ERROR', String(message.error.message ?? 'RPC provider error').slice(0,300));
    requireThat(object(message.result), 'RPC_RESULT_INVALID');
    return message.result;
  }
  const network = name => memo(networks,name,async () => {
    const definition = NETWORKS[name];
    requireThat(definition, 'UNSUPPORTED_NETWORK');
    const endpoint = resolveSacRpcEndpoint(name,endpoints,environment), result = await rpc(endpoint,'getNetwork');
    requireThat(result.passphrase === definition.passphrase, 'RPC_NETWORK_PASSPHRASE_MISMATCH');
    return {name,endpoint,passphrase:definition.passphrase,protocolVersion:result.protocolVersion ?? null};
  });
  async function query(context, contractId, method, args = []) {
    // Match the original SDK's unsigned read source. It has no private key.
    const transaction = new sdk.TransactionBuilder(new sdk.Account(sdk.contract.NULL_ACCOUNT,'0'),
      {fee:sdk.BASE_FEE,networkPassphrase:context.passphrase})
      .addOperation(new sdk.Contract(contractId).call(method,...args)).setTimeout(0).build();
    const result = await rpc(context.endpoint,'simulateTransaction',{transaction:transaction.toXDR()});
    requireThat(Number.isSafeInteger(result.latestLedger) && result.latestLedger > 0, 'RPC_LEDGER_INVALID');
    if (result.error) throw fault('TOKEN_READ_FAILED', String(result.error).slice(0,300));
    requireThat(!result.restorePreamble, 'TOKEN_STATE_RESTORATION_REQUIRED');
    requireThat(Array.isArray(result.results) && result.results.length === 1 &&
      typeof result.results[0].xdr === 'string' && typeof result.transactionData === 'string', 'TOKEN_READ_RESULT_INVALID');
    const entry = result.results[0], data = new sdk.SorobanDataBuilder(result.transactionData);
    requireThat((entry.auth ?? []).length === 0 && data.getReadWrite().length === 0,
      'TOKEN_GETTER_REQUIRES_AUTHORIZATION_OR_WRITE');
    return {value:sdk.scValToNative(sdk.xdr.ScVal.fromXDR(entry.xdr,'base64')),ledger:result.latestLedger};
  }
  const token = (name, asset) => memo(tokens,JSON.stringify([name,asset]),async () => {
    requireThat(sdk.StrKey.isValidContract(asset), 'ASSET_CONTRACT_ADDRESS_INVALID');
    const context = await network(name), key = new sdk.Contract(asset).getFootprint().toXDR('base64');
    const result = await rpc(context.endpoint,'getLedgerEntries',{keys:[key]});
    const instance = decodeSacInstance({result},asset,sdk);
    requireThat(instance.state !== 'SAC_INSTANCE_MISSING' && instance.liveUntilLedger >= result.latestLedger,
      'CONTRACT_INSTANCE_MISSING_OR_ARCHIVED');
    const kind = instance.executable;
    const sac = kind === 'contractExecutableStellarAsset';
    const decimals = await query(context,asset,'decimals');
    const symbol = await query(context,asset,'symbol');
    const nameResult = await query(context,asset,'name');
    requireThat(Number.isInteger(decimals.value) && decimals.value >= 0 && decimals.value <= 18, 'TOKEN_DECIMALS_UNSUPPORTED');
    requireThat(typeof symbol.value === 'string' && symbol.value.length <= 64 &&
      typeof nameResult.value === 'string' && nameResult.value.length <= 256, 'TOKEN_METADATA_INVALID');
    let classic = null;
    if (sac) {
      requireThat(decimals.value === 7, 'SAC_DECIMALS_MISMATCH');
      if (sdk.Asset.native().contractId(context.passphrase) === asset) classic = 'native';
      else {
        const match = /^([A-Za-z0-9]{1,12}):(G[A-Z2-7]{55})$/.exec(nameResult.value);
        requireThat(match && symbol.value === match[1] && sdk.StrKey.isValidEd25519PublicKey(match[2]), 'SAC_ASSET_IDENTITY_INVALID');
        requireThat(new sdk.Asset(match[1],match[2]).contractId(context.passphrase) === asset, 'SAC_CONTRACT_ID_MISMATCH');
        classic = {code:match[1],issuer:match[2]};
      }
    }
    return {network:name,asset,kind:sac?'STELLAR_ASSET_CONTRACT':'CUSTOM_CONTRACT',executable:kind,
      decimals:decimals.value,symbol:symbol.value,name:nameResult.value,classic,
      rpcOrigin:new URL(context.endpoint).origin,endpointDigest:hash(context.endpoint),
      instanceLedger:instance.latestLedger,liveUntilLedger:instance.liveUntilLedger,instance,
      metadataLedgers:[decimals.ledger,symbol.ledger,nameResult.ledger]};
  });
  const recipient = (name, asset, payTo) => memo(balances,JSON.stringify([name,asset,payTo]),async () => {
    requireThat(sdk.StrKey.isValidEd25519PublicKey(payTo) || sdk.StrKey.isValidContract(payTo), 'RECIPIENT_ADDRESS_INVALID');
    const context = await network(name), metadata = await token(name,asset), address = new sdk.Address(payTo).toScVal();
    const balance = await query(context,asset,'balance',[address]);
    requireThat(typeof balance.value === 'bigint' && balance.value >= 0n && balance.value < (1n << 127n), 'TOKEN_BALANCE_INVALID');
    let authorized = null, authorizationLedger = null;
    if (metadata.kind === 'STELLAR_ASSET_CONTRACT' && metadata.classic !== 'native') {
      const answer = await query(context,asset,'authorized',[address]);
      requireThat(typeof answer.value === 'boolean', 'TOKEN_AUTHORIZATION_INVALID');
      authorized = answer.value; authorizationLedger = answer.ledger;
    }
    return {payTo,balanceAtomic:String(balance.value),balanceLedger:balance.ledger,authorized,authorizationLedger};
  });
  return {network,token,recipient};
}

