export const NOTIFICATION_SCHEMA = 'stellar-forge.seller-incident-notification.v1';
export const MAX_PENDING = 1024;
const uuid = /^[a-f0-9-]{36}$/;
const terminal = event => ['DELIVERED','EXHAUSTED','CANCELLED'].includes(event.status);
