    const entry = {startedAtMs:now};
    entry.promise = Promise.resolve().then(read).then(value => ({value, startedAtMs:now}));
    cache.set(key, entry);
    entry.promise.catch(() => { if (cache.get(key) === entry) cache.delete(key); });
    return entry.promise;
