    if (typeof v === 'number' && Number.isFinite(v)) return JSON.stringify(v);
    if (Array.isArray(v)) return '[' + v.map(x => visit(x, depth + 1)).join(',') + ']';
    if (!plain(v)) throw fail('OPERATION_JSON_INVALID', 400);
